static int passed,failed;static wchar_t fixture[32768];
#define CHECK(label,c) do{if(c){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL line %d: %s\n",__LINE__,label);}}while(0)
static DWORD buffers(const char *a,const char *b,diff_result *r){return diff_buffers((const uint8_t*)a,strlen(a),(const uint8_t*)b,strlen(b),NULL,r);}
static int valid_rows(diff_result *r){uint32_t a=0,b=0;for(uint32_t i=0;i<r->count;i++){diff_row *row=&r->rows[i];if(row->left!=DIFF_NO_LINE&&row->left!=a++)return 0;if(row->right!=DIFF_NO_LINE&&row->right!=b++)return 0;if(row->kind==DIFF_SAME){if(row->left==DIFF_NO_LINE||row->right==DIFF_NO_LINE)return 0;diff_line *x=&r->doc[0].lines[row->left],*y=&r->doc[1].lines[row->right];if(x->length!=y->length||x->newline!=y->newline||wmemcmp(r->doc[0].data.text+x->start,r->doc[1].data.text+y->start,x->length))return 0;}else if(!row->hunk)return 0;}return a==r->doc[0].count&&b==r->doc[1].count;}
static void test_diff_alignment_and_change_navigation(void){diff_result r={0};CHECK("aligned insert, delete and replace",!buffers("same\nold\nkeep\nremoved\nlast\n","same\nnew\nkeep\nlast\nadded\n",&r)&&r.mode==DIFF_TEXT&&r.hunks==3&&!r.bytes_equal&&valid_rows(&r));int first=diff_change(&r,-1,1),second=diff_change(&r,first,1),third=diff_change(&r,second,1);CHECK("change navigation wraps in both directions",first==1&&second==3&&third==5&&diff_change(&r,third,1)==first&&diff_change(&r,first,-1)==third);diff_free(&r);CHECK("empty files are complete and equal",!buffers("","",&r)&&r.bytes_equal&&!r.count&&!r.hunks);diff_free(&r);CHECK("empty left uses explicit insertion gaps",!buffers("","a\nb\n",&r)&&r.count==2&&r.rows[0].left==DIFF_NO_LINE&&r.rows[1].kind==DIFF_ADDED&&valid_rows(&r));diff_free(&r);CHECK("empty right uses explicit deletion gaps",!buffers("a\n","",&r)&&r.count==1&&r.rows[0].right==DIFF_NO_LINE&&r.rows[0].kind==DIFF_REMOVED&&valid_rows(&r));diff_free(&r);CHECK("missing final newline is a real text difference",!buffers("a\n","a",&r)&&r.hunks==1&&r.rows[0].kind==DIFF_CHANGED);diff_free(&r);CHECK("normalized CRLF is distinguished from byte equality",!buffers("a\r\nb\r\n","a\nb\n",&r)&&!r.bytes_equal&&!r.hunks&&valid_rows(&r));diff_free(&r);}
static uint32_t random_state=918273;static uint32_t random_value(void){random_state=random_state*1664525+1013904223;return random_state;}
static void test_diff_random_alignment_against_lcs_oracle(void){int correct=1;for(int trial=0;trial<500;trial++){int n=(int)(random_value()%25),m=(int)(random_value()%25);char a[100],b[100];int lcs[26][26]={{0}};for(int i=0;i<n;i++){a[2*i]=(char)('a'+random_value()%6);a[2*i+1]='\n';}a[2*n]=0;for(int i=0;i<m;i++){b[2*i]=(char)('a'+random_value()%6);b[2*i+1]='\n';}b[2*m]=0;for(int i=1;i<=n;i++)for(int j=1;j<=m;j++)lcs[i][j]=a[2*i-2]==b[2*j-2]?lcs[i-1][j-1]+1:lcs[i-1][j]>lcs[i][j-1]?lcs[i-1][j]:lcs[i][j-1];diff_result r={0};if(buffers(a,b,&r)||!valid_rows(&r))correct=0;int edits=0;for(uint32_t i=0;i<r.count;i++)if(r.rows[i].kind!=DIFF_SAME)edits+=(r.rows[i].left!=DIFF_NO_LINE)+(r.rows[i].right!=DIFF_NO_LINE);if(edits!=n+m-2*lcs[n][m]||r.coarse)correct=0;diff_free(&r);}CHECK("500 deterministic alignments preserve both inputs and match an independent LCS edit oracle",correct);}
static void test_diff_encoding_binary_and_bounded_fallback(void){diff_result r={0};const uint16_t utf16[]={0xfeff,'c','a','f',0xe9,'\r','\n'};CHECK("UTF-16 BOM and UTF-8 share normalized text",!diff_buffers((void*)utf16,sizeof utf16,(void*)"café\n",6,NULL,&r)&&!r.hunks&&!r.bytes_equal&&r.doc[0].data.encoding==TEXT_UTF16LE);diff_free(&r);const uint8_t a[]={0,1,0,0,255,4},b[]={0,1,0,0,255,5};CHECK("binary equality covers complete bytes",!diff_buffers(a,sizeof a,a,sizeof a,NULL,&r)&&r.mode==DIFF_BINARY&&r.bytes_equal);diff_free(&r);CHECK("binary differences are reported",!diff_buffers(a,sizeof a,b,sizeof b,NULL,&r)&&r.mode==DIFF_BINARY&&!r.bytes_equal);diff_free(&r);
 char *left=malloc(24020),*right=malloc(24020);strcpy(left,"prefix\n");strcpy(right,"prefix\n");size_t at=7;for(int i=0;i<3000;i++){at+=(size_t)sprintf(left+at,"a%04d\n",i);}strcpy(left+at,"suffix\n");at=7;for(int i=0;i<3000;i++)at+=(size_t)sprintf(right+at,"b%04d\n",i);strcpy(right+at,"suffix\n");CHECK("large rewrite falls back with preserved prefix, suffix and explicit coarse status",!buffers(left,right,&r)&&r.coarse&&r.hunks==1&&valid_rows(&r)&&r.rows[0].kind==DIFF_SAME&&r.rows[r.count-1].kind==DIFF_SAME);diff_free(&r);free(left);free(right);
 char *many=malloc(200004);for(int i=0;i<100001;i++){many[2*i]='x';many[2*i+1]='\n';}many[200002]=0;CHECK("line cap reports summary instead of partial text equality",!buffers(many,many,&r)&&r.mode==DIFF_LARGE&&r.bytes_equal&&!r.rows);diff_free(&r);free(many);HANDLE cancel=CreateEventW(NULL,TRUE,TRUE,NULL);CHECK("cancelled comparison cannot report ready",diff_buffers(a,sizeof a,b,sizeof b,cancel,&r)==ERROR_CANCELLED);diff_free(&r);CloseHandle(cancel);}
static void fullpath(wchar_t out[32768],const wchar_t *name){swprintf(out,32768,L"%ls\\%ls",fixture,name);}
static int put(const wchar_t *name,const void *data,DWORD n){wchar_t p[32768];fullpath(p,name);HANDLE f=CreateFileW(p,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);if(f==INVALID_HANDLE_VALUE)return 0;DWORD done=0;int ok=WriteFile(f,data,n,&done,NULL)&&done==n;CloseHandle(f);return ok;}
static void test_diff_file_reader_errors_and_full_byte_summary(void){wchar_t temp[32768],a[32768],b[32768];GetTempPathW(32768,temp);swprintf(fixture,32768,L"%lsopenpilot-diff-%lu-%llu",temp,(unsigned long)GetCurrentProcessId(),(unsigned long long)GetTickCount64());CHECK("fresh owned diff fixture",CreateDirectoryW(fixture,NULL));CHECK("small comparison fixture bytes",put(L"left.txt","a\nold\nend\n",10)&&put(L"right.txt","a\nnew\nend\n",10));fullpath(a,L"left.txt");fullpath(b,L"right.txt");diff_result r={0};CHECK("actual Windows files are compared read-only",!diff_files(a,b,0,NULL,&r)&&r.hunks==1&&r.doc[0].bytes==10&&r.doc[1].bytes==10);diff_free(&r);HANDLE held=CreateFileW(a,GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);CHECK("private held-writer fixture opened",held!=INVALID_HANDLE_VALUE);CHECK("source writer prevents an equality conclusion",diff_files(a,b,0,NULL,&r)!=0&&!r.rows);diff_free(&r);if(held!=INVALID_HANDLE_VALUE)CloseHandle(held);CHECK("directory inputs fail visibly",diff_files(fixture,b,0,NULL,&r)==ERROR_NOT_SUPPORTED);diff_free(&r);wchar_t missing[32768];fullpath(missing,L"missing");CHECK("missing inputs are errors",diff_files(a,missing,0,NULL,&r)!=0);diff_free(&r);
 size_t bytes=DIFF_TEXT_BYTES+17;uint8_t *large=malloc(bytes);memset(large,'z',bytes);CHECK("oversized full-byte fixtures",put(L"large-a",large,(DWORD)bytes)&&put(L"large-b",large,(DWORD)bytes));fullpath(a,L"large-a");fullpath(b,L"large-b");CHECK("oversized identical files use full equality, no prefix claim",!diff_files(a,b,0,NULL,&r)&&r.mode==DIFF_LARGE&&r.bytes_equal&&r.doc[0].bytes==bytes);diff_free(&r);HANDLE file=CreateFileW(b,GENERIC_WRITE,0,NULL,OPEN_EXISTING,0,NULL);LARGE_INTEGER offset={.QuadPart=(LONGLONG)bytes-1};DWORD done=0;CHECK("tail difference written beyond text limit",file!=INVALID_HANDLE_VALUE&&SetFilePointerEx(file,offset,NULL,FILE_BEGIN)&&WriteFile(file,"!",1,&done,NULL)&&done==1);if(file!=INVALID_HANDLE_VALUE)CloseHandle(file);CHECK("difference at the final byte beyond text limit is found",!diff_files(a,b,0,NULL,&r)&&!r.bytes_equal&&r.mode==DIFF_LARGE);diff_free(&r);free(large);}
static void test_diff_wsl_provider_and_disabled_gate(void){wchar_t root[32768],a[32768],b[32768];DWORD n=GetEnvironmentVariableW(L"OPENPILOT_DIFF_WSL_FIXTURE",root,32768);CHECK("owned native Linux file fixture supplied",n>0&&n<32768);if(!n||n>=32768)return;swprintf(a,32768,L"%ls\\left.txt",root);swprintf(b,32768,L"%ls\\right.txt",root);diff_result r={0};CHECK("disabled WSL never opens the provider",diff_files(a,b,0,NULL,&r)==ERROR_NOT_SUPPORTED);diff_free(&r);CHECK("WSL UNC file comparison uses shared text semantics",!diff_files(a,b,1,NULL,&r)&&r.hunks==1&&valid_rows(&r));diff_free(&r);fullpath(a,L"left.txt");swprintf(b,32768,L"%ls\\left.txt",root);CHECK("mixed Windows and Linux endpoints compare equal bytes",!diff_files(a,b,1,NULL,&r)&&r.bytes_equal&&!r.hunks);diff_free(&r);}
static void wait_worker(void){uint64_t end=GetTickCount64()+10000;while(A.thread&&GetTickCount64()<end){Sleep(5);tick();}}
static void test_diff_panel_navigation_supersession_and_hidden_reuse(void){A.dpi=96;A.shown=1;A.selected=-1;A.cancel=CreateEventW(NULL,TRUE,FALSE,NULL);A.out=CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);fonts();HANDLE section=CreateFileMappingW(INVALID_HANDLE_VALUE,NULL,PAGE_READWRITE,0,1100*650*8,NULL);CHECK("real diff panel maps its offscreen buffers",map(section,1100,650));wchar_t a[32768],b[32768];fullpath(a,L"left.txt");fullpath(b,L"right.txt");diff_open request={.session=11};queue(a,b,&request);wait_worker();CHECK("actual worker publishes immutable comparison",A.ready&&!A.thread&&A.result.hunks==1);A.request.wsl=1;A.run_wsl=1;struct {panelp_head h;uint32_t enabled;} policy={{PANELP_DIFF_WSL_POLICY,4},0};on_host((msg*)&policy);CHECK("policy intake preserves completed Windows results and captured worker policy",!A.request.wsl&&!A.queued_request.wsl&&A.run_wsl==1&&A.ready&&A.result.hunks==1);begin();wait_worker();CHECK("next Windows worker captures disabled WSL policy",!A.thread&&!A.run_wsl&&A.ready&&A.result.hunks==1);input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_F7});CHECK("F7 focuses a real aligned change",A.selected==1&&A.result.rows[A.selected].hunk==1);input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_RIGHT});CHECK("horizontal offset is shared by both sides",A.column==4);A.column=0;
 request.session++;queue(a,a,&request);request.session++;queue(a,b,&request);wait_worker();CHECK("rapid pair changes publish only the latest session",A.ready&&A.request.session==13&&A.result.hunks==1&&!A.queued[0]);A.shown=0;tick();uint64_t session=A.request.session;queue(a,b,&request);CHECK("hidden comparison reuse does not restart I/O",A.ready&&!A.thread&&A.request.session==session);A.shown=1;A.waiting=A.pending=0;int bank=A.next;tick();CHECK("idle comparison does not resend frames",A.next==bank&&!A.waiting);
 request.session++;queue(a,b,&request);stop();wait_worker();CHECK("Stop cannot expose an incomplete result as ready",!A.ready&&A.result.error==ERROR_CANCELLED);begin();wait_worker();CHECK("Refresh recovers from Stop",A.ready&&A.result.hunks==1);A.selected=1;paint();GdiFlush();wchar_t shot[32768];if(GetEnvironmentVariableW(L"OPENPILOT_DIFF_SCREENSHOT",shot,32768)){BITMAPINFOHEADER bi={sizeof bi,A.w,-A.h,1,32,BI_RGB};BITMAPFILEHEADER fh={.bfType=0x4d42,.bfSize=(DWORD)(sizeof fh+sizeof bi+A.w*A.h*4),.bfOffBits=sizeof fh+sizeof bi};HANDLE f=CreateFileW(shot,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);if(f!=INVALID_HANDLE_VALUE){io(f,&fh,sizeof fh,1);io(f,&bi,sizeof bi,1);io(f,A.pixels,A.w*A.h*4,1);CloseHandle(f);}}
 diff_free(&A.result);diff_free(&A.work);for(int i=0;i<2;i++){free(A.path[i]);free(A.queued[i]);}CloseHandle(A.out);CloseHandle(A.cancel);if(A.shared)UnmapViewOfFile(A.shared);CloseHandle(A.section);SelectObject(A.dc,A.original);DeleteObject(A.bitmap);DeleteDC(A.dc);DeleteObject(A.font);DeleteObject(A.bold);DeleteObject(A.mono);memset(&A,0,sizeof A);}
static void cleanup(void){const wchar_t *names[]={L"left.txt",L"right.txt",L"large-a",L"large-b"};wchar_t p[32768];for(int i=0;i<4;i++){fullpath(p,names[i]);DeleteFileW(p);}RemoveDirectoryW(fixture);}
int wmain(void){SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);test_diff_alignment_and_change_navigation();test_diff_random_alignment_against_lcs_oracle();test_diff_encoding_binary_and_bounded_fallback();test_diff_file_reader_errors_and_full_byte_summary();test_diff_wsl_provider_and_disabled_gate();test_diff_panel_navigation_supersession_and_hidden_reuse();cleanup();printf("%d passed, %d failed; 6 diff selectors\n",passed,failed);return failed?1:0;}
